import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> {'side':..., 'price':..., 'qty':...}
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty
        seq = seq_counter
        seq_counter += 1

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                if sid not in book:
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and sp > price:
                    break
                resting = book[sid]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] == 0:
                    del book[sid]
                    heapq.heappop(sell_heap)
                # else keep resting order in place (partial fill), do not pop

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                bp_neg, bseq, bid = buy_heap[0]
                bp = -bp_neg
                if bid not in book:
                    heapq.heappop(buy_heap)
                    continue
                if price is not None and bp < price:
                    break
                resting = book[bid]
                trade_qty = min(remaining, resting['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] == 0:
                    del book[bid]
                    heapq.heappop(buy_heap)
                # else keep resting order in place (partial fill), do not pop

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

